/* glibc's own header for the interface joistmig's stubs are written to
   (the owner's decision, 2026-11-06: written for glibc, apart from Joist's
   header for its own programs; the two agree on the names below and on
   the message, nothing else).

   A message's body is the routine's in-line arguments in declaration
   order, each at an 8-byte boundary; a variable array is its count (a
   word) and then its elements.  The first three words of the body go in
   message registers 1-3, the rest in the thread's IPC buffer; register 0
   carries the routine's id (a request) or its return code (a reply) in
   its low half and the body's length in bytes in its high half.  A
   message passes up to two rights.

   Here a right to send is kept with its MIG disposition, so that
   joist_mig_call (joist-mig.c) can make it from the name table: a send
   right made from a receive right, a copy, or a move that gives up one
   user reference.  */

#ifndef _JOIST_MIG_H
#define _JOIST_MIG_H 1

#include <stddef.h>
#include <stdint.h>
#include <string.h>

#define JOIST_MIG_BUF_WORDS	512u		/* the IPC buffer */
#define JOIST_MIG_WORDS		(JOIST_MIG_BUF_WORDS + 3u)
#define JOIST_MIG_CAPS		2u

/* MIG's results (mach/mig_errors.h's values).  */
#define JOIST_MIG_TYPE_ERROR		(-300)
#define JOIST_MIG_REPLY_MISMATCH	(-301)
#define JOIST_MIG_BAD_ID		(-303)
#define JOIST_MIG_BAD_ARGUMENTS		(-304)
#define JOIST_MIG_NO_REPLY		(-305)
#define JOIST_MIG_ARRAY_TOO_LARGE	(-307)

struct joist_mig_msg
{
  uint64_t r[4];
  uint32_t ncaps;
  uint32_t cap[JOIST_MIG_CAPS];	/* names: what to send, or where it came */
  uint8_t disp[JOIST_MIG_CAPS];	/* to send: the MIG disposition */
  uint32_t len;			/* words in BUF */
  uint64_t *buf;		/* JOIST_MIG_BUF_WORDS words */
  uint64_t badge;		/* received: the sender's badge */
};

/* A server's routine (what <demuxer>_routine returns for a message's id;
   MIG's mig_routine_t, on Joist messages).  */
typedef void (*joist_mig_routine_t) (struct joist_mig_msg *in,
				     struct joist_mig_msg *out);

/* The runtime's (joist-mig.c), under glibc's reserved names: generated
   code says joist_mig_*, which a program may use for itself.  */
#define joist_mig_call __joist_mig_call
#define joist_mig_allocate __joist_mig_allocate
#define joist_mig_deallocate __joist_mig_deallocate

/* A call on the port named PORT, the reply in *M; 0 or a Mach error.  */
extern int joist_mig_call (uint32_t port, struct joist_mig_msg *m);
/* Memory for what MIG would have sent out of line, and its release.  */
extern void *joist_mig_allocate (size_t size);
extern void joist_mig_deallocate (void *p, size_t size);

/* A body being built or read: bytes [0, END), the next field at AT.  */
struct joist_mig_body
{
  uint64_t w[JOIST_MIG_WORDS];
  size_t at, end;
};

/* The 8-byte boundary at or after N.  */
static inline size_t
joist_mig_align (size_t n)
{
  return (n + 7) & ~(size_t) 7;
}

/* Add N bytes from P: -1 if they don't fit.  */
static inline int
joist_mig_put (struct joist_mig_body *b, const void *p, size_t n)
{
  size_t start = joist_mig_align (b->at);
  if (start > sizeof b->w || n > sizeof b->w - start)
    return -1;
  memcpy ((unsigned char *) b->w + start, p, n);
  b->end = b->at = start + n;
  return 0;
}

/* Take N bytes into P: -1 if fewer are left.  */
static inline int
joist_mig_get (struct joist_mig_body *b, void *p, size_t n)
{
  size_t start = joist_mig_align (b->at);
  if (start > b->end || n > b->end - start)
    return -1;
  memcpy (p, (const unsigned char *) b->w + start, n);
  b->at = start + n;
  return 0;
}

/* The next N bytes where they are: NULL if fewer are left.  */
static inline void *
joist_mig_ref (struct joist_mig_body *b, size_t n)
{
  size_t start = joist_mig_align (b->at);
  if (start > b->end || n > b->end - start)
    return NULL;
  b->at = start + n;
  return (unsigned char *) b->w + start;
}

/* The id or return code in register 0.  */
static inline uint32_t
joist_mig_code (const struct joist_mig_msg *m)
{
  return (uint32_t) (m->r[0] & 0xffffffffu);
}

/* B into M: its length beside the code, three words in registers, the
   rest in the buffer.  */
static inline void
joist_mig_send (struct joist_mig_msg *m, const struct joist_mig_body *b)
{
  size_t nw = joist_mig_align (b->end) / 8;
  m->r[0] = (m->r[0] & 0xffffffffu) | ((uint64_t) b->end << 32);
  m->r[1] = nw > 0 ? b->w[0] : 0;
  m->r[2] = nw > 1 ? b->w[1] : 0;
  m->r[3] = nw > 2 ? b->w[2] : 0;
  m->len = nw > 3 ? (uint32_t) (nw - 3) : 0;
  if (m->len > 0)
    memcpy (m->buf, &b->w[3], (size_t) m->len * 8);
}

/* M's body into B, to read: -1 if its length can't be what came (more
   than a message holds, or not the words that arrived).  */
static inline int
joist_mig_recv (const struct joist_mig_msg *m, struct joist_mig_body *b)
{
  size_t bytes = (size_t) (m->r[0] >> 32);
  size_t nw = joist_mig_align (bytes) / 8;
  if (m->ncaps > JOIST_MIG_CAPS || m->len > JOIST_MIG_BUF_WORDS
      || nw > JOIST_MIG_WORDS || m->len != (nw > 3 ? nw - 3 : 0))
    return -1;
  b->w[0] = m->r[1];
  b->w[1] = m->r[2];
  b->w[2] = m->r[3];
  if (m->len > 0)
    memcpy (&b->w[3], m->buf, (size_t) m->len * 8);
  b->at = 0;
  b->end = bytes;
  return 0;
}

/* The right NAME, with MIG's DISPOSITION, sent with M: -1 if M has its
   two already.  */
static inline int
joist_mig_right (struct joist_mig_msg *m, uint32_t name, int disposition)
{
  if (m->ncaps >= JOIST_MIG_CAPS)
    return -1;
  m->cap[m->ncaps] = name;
  m->disp[m->ncaps] = (uint8_t) disposition;
  m->ncaps++;
  return 0;
}

#endif
